# Notebook cell 266: # @title  Persistent CPU Trajectory Farm
_PHASE3K_WORKER_THREAD_LIMITER = None

def phase3k_farm_worker_initializer():
    """
    Configure each worker as a single-threaded simulation process.

    Why?
    ----
    We want:

        6 worker processes
        ~= 6 occupied CPU cores

    NOT:

        6 Python workers
        x hidden BLAS/OpenMP threads
        = severe oversubscription.
    """

    global _PHASE3K_WORKER_THREAD_LIMITER


    os.environ[
        "OMP_NUM_THREADS"
    ] = "1"

    os.environ[
        "MKL_NUM_THREADS"
    ] = "1"

    os.environ[
        "OPENBLAS_NUM_THREADS"
    ] = "1"

    os.environ[
        "NUMEXPR_NUM_THREADS"
    ] = "1"


    # Existing NumPy thread pools may already have been initialized
    # before fork. threadpoolctl handles those as well.
    try:

        from threadpoolctl import (
            threadpool_limits
        )


        _PHASE3K_WORKER_THREAD_LIMITER = (
            threadpool_limits(
                limits=1
            )
        )


        _PHASE3K_WORKER_THREAD_LIMITER.__enter__()


    except Exception:

        _PHASE3K_WORKER_THREAD_LIMITER = None

def phase3k_farm_normalize_payload(
    result
):

    if isinstance(
        result,
        dict
    ):

        return dict(
            result
        )


    if is_dataclass(
        result
    ):

        return asdict(
            result
        )


    raise TypeError(

        "Trajectory simulator returned unsupported type: "
        f"{type(result)}"
    )

def phase3k_farm_worker(
    pair_index
):
    """
    Calculate ONE independent physical Bell-pair trajectory.

    The worker:
        - does not read the trajectory cache
        - does not write Google Drive
        - does not modify parent state
        - returns only a compact Python payload
    """

    pair_index = int(
        pair_index
    )


    wall_start = (
        time.perf_counter()
    )


    cpu_start = (
        time.process_time()
    )


    result = (
        phase3k_simulate_one_fast_hardware_lane(

            pair_index=(
                pair_index
            ),

            total_distance_km=(
                PHASE3K_FARM_DISTANCE_KM
            ),

            repeater_count=(
                PHASE3K_FARM_REPEATER_COUNT
            ),

            mode_count=(
                PHASE3K_FARM_MODE_COUNT
            ),

            z_probability=(
                PHASE3K_FARM_Z_PROBABILITY
            ),

            max_slots_per_pair=(
                PHASE3K_FARM_MAX_SLOTS_PER_PAIR
            )
        )
    )


    payload = (
        phase3k_farm_normalize_payload(
            result
        )
    )


    cpu_s = (

        time.process_time()
        -
        cpu_start
    )


    wall_s = (

        time.perf_counter()
        -
        wall_start
    )


    return {

        "pair_index":
            pair_index,

        "worker_pid":
            os.getpid(),

        "worker_cpu_s":
            float(
                cpu_s
            ),

        "worker_wall_s":
            float(
                wall_s
            ),

        "payload":
            payload
    }

class NARADFarmSystemMonitor:

    def __init__(
        self,
        interval_s=0.25
    ):

        self.interval_s = float(
            interval_s
        )

        self.cpu_samples = []

        self.available_ram_samples_gib = []

        self._stop_event = (
            threading.Event()
        )

        self._thread = None


    def _run(
        self
    ):

        # Prime psutil's CPU measurement.
        psutil.cpu_percent(
            interval=None
        )


        while not self._stop_event.wait(
            self.interval_s
        ):

            self.cpu_samples.append(

                psutil.cpu_percent(
                    interval=None
                )
            )


            vm = (
                psutil.virtual_memory()
            )


            self.available_ram_samples_gib.append(

                vm.available
                /
                (1024**3)
            )


    def start(
        self
    ):

        self._thread = (
            threading.Thread(

                target=(
                    self._run
                ),

                daemon=True
            )
        )


        self._thread.start()


    def stop(
        self
    ):

        self._stop_event.set()


        if (
            self._thread
            is not None
        ):

            self._thread.join(
                timeout=2.0
            )


    def summary(
        self
    ):

        if self.cpu_samples:

            mean_cpu = float(
                np.mean(
                    self.cpu_samples
                )
            )

            peak_cpu = float(
                np.max(
                    self.cpu_samples
                )
            )

        else:

            mean_cpu = float(
                "nan"
            )

            peak_cpu = float(
                "nan"
            )


        if (
            self.available_ram_samples_gib
        ):

            minimum_available_ram = float(

                np.min(
                    self.available_ram_samples_gib
                )
            )

        else:

            minimum_available_ram = float(
                "nan"
            )


        return {

            "mean_system_cpu_percent":
                mean_cpu,

            "peak_system_cpu_percent":
                peak_cpu,

            "minimum_available_ram_gib":
                minimum_available_ram
        }

def phase3k_run_trajectory_farm(
    pair_indices,
    workers,
    progress_every=8
):

    pair_indices = tuple(

        int(
            pair_index
        )

        for pair_index
        in pair_indices
    )


    workers = int(
        workers
    )


    if workers < 1:

        raise ValueError(
            "workers must be positive."
        )


    if (
        workers
        >
        psutil.cpu_count(
            logical=True
        )
    ):

        raise ValueError(

            "Requested more workers than "
            "available logical CPUs."
        )


    print(
        "\n" + "-" * 100
    )

    print(
        f"Starting trajectory farm: "
        f"W={workers}, "
        f"N={len(pair_indices)}"
    )

    print(
        "-" * 100
    )


    # Clean parent-side garbage before FORK.
    gc.collect()


    monitor = (
        NARADFarmSystemMonitor()
    )


    context = (
        mp.get_context(
            "fork"
        )
    )


    results = []


    wall_start = (
        time.perf_counter()
    )


    monitor.start()


    try:

        # --------------------------------------------------------
        # Pool workers are persistent.
        #
        # chunksize=1 gives dynamic load balancing.
        # --------------------------------------------------------

        with context.Pool(

            processes=(
                workers
            ),

            initializer=(
                phase3k_farm_worker_initializer
            )

        ) as pool:


            iterator = (
                pool.imap_unordered(

                    phase3k_farm_worker,

                    pair_indices,

                    chunksize=1
                )
            )


            for completed_count, result in enumerate(
                iterator,
                start=1
            ):

                results.append(
                    result
                )


                if (
                    completed_count == 1
                    or
                    completed_count % progress_every == 0
                    or
                    completed_count == len(
                        pair_indices
                    )
                ):

                    elapsed_s = (

                        time.perf_counter()
                        -
                        wall_start
                    )


                    rate = (

                        completed_count
                        /
                        elapsed_s
                    )


                    print(

                        f"[W={workers:>2}] "
                        f"{completed_count:>2}/"
                        f"{len(pair_indices)} complete | "
                        f"wall={elapsed_s:>8.2f}s | "
                        f"rate={rate:.3f} pairs/s"
                    )


    finally:

        monitor.stop()


    total_wall_s = (

        time.perf_counter()
        -
        wall_start
    )


    results.sort(

        key=lambda item:
            item[
                "pair_index"
            ]
    )


    # ============================================================
    # Sanity: exactly one result per requested pair.
    # ============================================================

    returned_indices = tuple(

        result[
            "pair_index"
        ]

        for result
        in results
    )


    if (

        returned_indices

        !=

        tuple(
            sorted(
                pair_indices
            )
        )
    ):

        raise RuntimeError(

            "Trajectory farm did not return "
            "exactly one result per pair index."
        )


    total_worker_cpu_s = float(

        sum(

            result[
                "worker_cpu_s"
            ]

            for result
            in results
        )
    )


    # Number of fully occupied CPU cores represented by the
    # measured process CPU time.
    effective_busy_cores = (

        total_worker_cpu_s
        /
        total_wall_s
    )


    monitor_summary = (
        monitor.summary()
    )


    worker_pids = tuple(

        sorted(

            set(

                result[
                    "worker_pid"
                ]

                for result
                in results
            )
        )
    )


    summary = {

        "workers":
            workers,

        "pairs":
            len(
                results
            ),

        "wall_time_s":
            total_wall_s,

        "pairs_per_s":

            len(
                results
            )
            /
            total_wall_s,

        "total_worker_cpu_s":
            total_worker_cpu_s,

        "effective_busy_cores":
            effective_busy_cores,

        "worker_processes_observed":
            len(
                worker_pids
            ),

        "mean_system_cpu_percent":
            monitor_summary[
                "mean_system_cpu_percent"
            ],

        "peak_system_cpu_percent":
            monitor_summary[
                "peak_system_cpu_percent"
            ],

        "minimum_available_ram_gib":
            monitor_summary[
                "minimum_available_ram_gib"
            ]
    }


    return (
        tuple(
            results
        ),
        summary
    )


# Notebook cell 267: # @title  Strict Trajectory Equivalence Checker
def phase3k_compare_trajectory_payloads(
    reference,
    candidate,
    abs_tol=PHASE3K_FARM_FLOAT_ABS_TOL
):

    differences = []


    # ============================================================
    # Exact discrete quantities
    # ============================================================

    for field_name in (
        PHASE3K_FARM_EXACT_FIELDS
    ):

        if (
            field_name
            not in reference
            or
            field_name
            not in candidate
        ):

            differences.append(

                (
                    field_name,
                    "MISSING_FIELD"
                )
            )

            continue


        if (

            reference[
                field_name
            ]

            !=

            candidate[
                field_name
            ]
        ):

            differences.append(

                (
                    field_name,

                    reference[
                        field_name
                    ],

                    candidate[
                        field_name
                    ]
                )
            )


    # ============================================================
    # Floating physical quantities
    # ============================================================

    for field_name in (
        PHASE3K_FARM_FLOAT_FIELDS
    ):

        if (
            field_name
            not in reference
            or
            field_name
            not in candidate
        ):

            differences.append(

                (
                    field_name,
                    "MISSING_FIELD"
                )
            )

            continue


        if not math.isclose(

            float(
                reference[
                    field_name
                ]
            ),

            float(
                candidate[
                    field_name
                ]
            ),

            rel_tol=0.0,

            abs_tol=(
                abs_tol
            )
        ):

            differences.append(

                (
                    field_name,

                    reference[
                        field_name
                    ],

                    candidate[
                        field_name
                    ]
                )
            )


    return tuple(
        differences
    )

def phase3k_validate_farm_against_reference(
    reference_by_index,
    candidate_results
):

    failures = []


    for result in candidate_results:

        pair_index = int(
            result[
                "pair_index"
            ]
        )


        candidate_payload = (
            result[
                "payload"
            ]
        )


        if (
            pair_index
            not in
            reference_by_index
        ):

            failures.append(

                (
                    pair_index,
                    "PAIR_NOT_IN_REFERENCE"
                )
            )

            continue


        differences = (
            phase3k_compare_trajectory_payloads(

                reference=(
                    reference_by_index[
                        pair_index
                    ]
                ),

                candidate=(
                    candidate_payload
                )
            )
        )


        if differences:

            failures.append(

                (
                    pair_index,
                    differences
                )
            )


    return tuple(
        failures
    )
